-- Run ONLY on a disposable database after bootstrap.sql, 01_schema.sql,
-- seed_v3.sql and 04_upgrade_v4.sql. No real service credentials are used.
CREATE FUNCTION public.test_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
 IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'ASSERT FAILED: %',label;END IF;RAISE NOTICE 'PASS: %',label;END $$;
CREATE FUNCTION public.test_error(stmt text,fragment text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
 BEGIN EXECUTE stmt;EXCEPTION WHEN OTHERS THEN IF strpos(SQLERRM,fragment)>0 THEN RAISE NOTICE 'PASS expected error: %',fragment;RETURN;ELSE RAISE;END IF;END;
 RAISE EXCEPTION 'EXPECTED ERROR NOT RAISED: %',fragment;END $$;
SELECT public.test_assert((SELECT name='이전 버전 보존 시험품' FROM public.dnm_portal_products WHERE code='LEGACY-V3'),'v3 product preserved');
SELECT public.test_assert((SELECT count(*)=4 FROM auth.users),'v3 auth users preserved');
SELECT public.test_assert((SELECT body='기존 메모 유지' FROM public.dnm_portal_notes WHERE title='v3 보존'),'v3 note preserved');
SELECT public.test_assert(NOT has_table_privilege('authenticated','public.dnm_v4_records','INSERT'),'direct insert denied');
SELECT public.test_assert(NOT has_table_privilege('authenticated','public.dnm_v4_records','UPDATE'),'direct update denied');
SELECT public.test_assert(NOT has_function_privilege('authenticated','public.dnm_v4_put(text,text,text,text,uuid,jsonb,uuid,integer)','EXECUTE'),'private helper denied');
SELECT public.test_assert(NOT has_function_privilege('anon','public.dnm_v4_command(text,jsonb,uuid)','EXECUTE'),'anonymous commands denied');
DO $$
DECLARE a uuid:='11111111-1111-4111-8111-111111111111';b uuid:='22222222-2222-4222-8222-222222222222';w uuid:='33333333-3333-4333-8333-333333333333';v uuid:='44444444-4444-4444-8444-444444444444';
 k uuid;r jsonb;r2 jsonb;payload jsonb;oid uuid;rid uuid;opid uuid;eid uuid;wid uuid;prid uuid;receiptid uuid;sid uuid;wlid uuid;rowx public.dnm_v4_records;
BEGIN
 PERFORM set_config('request.jwt.claim.sub',a::text,true);
 PERFORM public.test_assert(public.dnm_v4_context()->>'version'='4.0.0','context version');
 PERFORM public.dnm_v4_command('save_master',jsonb_build_object('kind','equipment','code','EQ-TEST','title','시험설비','data',jsonb_build_object('active',true,'manager_id',a)),gen_random_uuid());
 SELECT id INTO eid FROM public.dnm_v4_records WHERE kind='equipment' AND code='EQ-TEST';
 PERFORM public.dnm_v4_command('save_master',jsonb_build_object('kind','employee','code','EMP-TEST','title','시험작업자','data',jsonb_build_object('active',true,'profile_id',w,'department','생산')),gen_random_uuid());
 SELECT id INTO wid FROM public.dnm_v4_records WHERE kind='employee' AND code='EMP-TEST';
 PERFORM public.dnm_v4_command('save_master',jsonb_build_object('kind','assignment','code','MAP-TEST','title','시험배정','data',jsonb_build_object('equipment_id',eid,'employee_id',wid,'active',true,'processes',jsonb_build_array('시험가공'))),gen_random_uuid());
 payload:=jsonb_build_object('data',jsonb_build_object('production_no','TEST-ORDER','customer','시험고객','part_no','SAMPLE-PART','part_name','가상 품목','qty',10,'priority','NORMAL'));
 k:=gen_random_uuid();r:=public.dnm_v4_command('save_order',payload,k);oid:=(r->>'id')::uuid;r2:=public.dnm_v4_command('save_order',payload,k);
 PERFORM public.test_assert(r=r2,'same request id returns same response');
 PERFORM public.test_assert((SELECT count(*)=1 FROM public.dnm_v4_records WHERE kind='order' AND code='TEST-ORDER'),'same request not duplicated');
 PERFORM public.test_error(format('SELECT public.dnm_v4_command(%L,%L::jsonb,%L::uuid)','save_order',jsonb_set(payload,'{data,qty}','11')::text,k),'같은 요청번호');
 r:=public.dnm_v4_command('save_routing',jsonb_build_object('order_id',oid,'manager_id',a,'lot','LOT-TEST','steps',jsonb_build_array(jsonb_build_object('code','010','name','시험가공','kind','WORK'))),gen_random_uuid());rid:=(r->>'id')::uuid;
 SELECT id INTO opid FROM public.dnm_v4_records WHERE kind='operation' AND parent_id=rid;
 SELECT * INTO rowx FROM public.dnm_v4_records WHERE id=rid;
 PERFORM public.test_error(format('SELECT public.dnm_v4_command(%L,%L::jsonb,gen_random_uuid())','release_routing',jsonb_build_object('id',rid,'version',rowx.version)::text),'먼저 배정');
 SELECT * INTO rowx FROM public.dnm_v4_records WHERE id=opid;
 PERFORM public.dnm_v4_command('assign_operation',jsonb_build_object('id',opid,'version',rowx.version,'equipment_id',eid,'employee_id',wid),gen_random_uuid());
 SELECT * INTO rowx FROM public.dnm_v4_records WHERE id=rid;
 PERFORM public.dnm_v4_command('release_routing',jsonb_build_object('id',rid,'version',rowx.version),gen_random_uuid());
 PERFORM set_config('request.jwt.claim.sub',w::text,true);
 SELECT * INTO rowx FROM public.dnm_v4_records WHERE id=opid;
 r:=public.dnm_v4_command('start_work',jsonb_build_object('id',opid,'version',rowx.version),gen_random_uuid());wlid:=(r->>'id')::uuid;
 PERFORM public.test_assert((SELECT state='ACTIVE' FROM public.dnm_v4_records WHERE id=wlid),'assigned worker start');
 SELECT * INTO rowx FROM public.dnm_v4_records WHERE id=opid;
 PERFORM public.test_error(format('SELECT public.dnm_v4_command(%L,%L::jsonb,gen_random_uuid())','start_work',jsonb_build_object('id',opid,'version',rowx.version)::text),'작업 가능한');
 -- Test fixture time travel, executed as postgres only. Not an app capability.
 UPDATE public.dnm_v4_records SET data=data||jsonb_build_object('start_at',now()-interval '1 hour') WHERE id=wlid;
 SELECT * INTO rowx FROM public.dnm_v4_records WHERE id=wlid;
 PERFORM public.dnm_v4_command('finish_work',jsonb_build_object('id',wlid,'version',rowx.version,'pending',true),gen_random_uuid());
 PERFORM public.test_assert((SELECT state='PENDING' FROM public.dnm_v4_records WHERE id=opid),'unknown quantity holds progress');
 SELECT * INTO rowx FROM public.dnm_v4_records WHERE id=wlid;
 PERFORM public.test_error(format('SELECT public.dnm_v4_command(%L,%L::jsonb,gen_random_uuid())','confirm_work',jsonb_build_object('id',wlid,'version',rowx.version,'total',10,'defect',11)::text),'불량수량');
 PERFORM public.dnm_v4_command('confirm_work',jsonb_build_object('id',wlid,'version',rowx.version,'total',10,'defect',0),gen_random_uuid());
 PERFORM public.test_assert((SELECT state='DONE' AND (data->>'confirmed_qty')::integer=10 FROM public.dnm_v4_records WHERE id=opid),'confirmed quantity completes operation');
 PERFORM set_config('request.jwt.claim.sub',a::text,true);
 SELECT * INTO rowx FROM public.dnm_v4_records WHERE id=oid;
 PERFORM public.dnm_v4_command('quality',jsonb_build_object('id',oid,'version',rowx.version,'stage','FINAL','total',10,'defect',0,'report_no','TEST-QA'),gen_random_uuid());
 PERFORM public.test_error(format('SELECT public.dnm_v4_command(%L,%L::jsonb,gen_random_uuid())','ship',jsonb_build_object('id',oid,'version',rowx.version,'qty',11,'delivery_no','TEST-DLV')::text),'최종 합격수량');
 PERFORM public.dnm_v4_command('ship',jsonb_build_object('id',oid,'version',rowx.version,'qty',10,'delivery_no','TEST-DLV'),gen_random_uuid());
 SELECT * INTO rowx FROM public.dnm_v4_records WHERE id=wlid;
 PERFORM public.test_error(format('SELECT public.dnm_v4_command(%L,%L::jsonb,gen_random_uuid())','cancel_work',jsonb_build_object('id',wlid,'version',rowx.version,'reason','시험')::text),'검사·출하 이력');
 SELECT * INTO rowx FROM public.dnm_v4_records WHERE id=oid;
 PERFORM public.dnm_v4_command('order_close',jsonb_build_object('id',oid,'version',rowx.version,'reason','출하 대조 완료'),gen_random_uuid());
 PERFORM public.test_assert((SELECT state='CLOSED' FROM public.dnm_v4_records WHERE id=oid),'customer order closed after shipment');
 PERFORM public.test_assert(public.dnm_v4_minutes('2026-10-01T07:30:00+09:00','2026-10-01T16:30:00+09:00')=460,'07:30-16:30 less defined breaks = 460 minutes');
 -- Purchase, approval, receiving and settlement.
 PERFORM set_config('request.jwt.claim.sub',w::text,true);
 payload:=jsonb_build_object('data',jsonb_build_object('supplier','시험공급사','tax_rate',0.1,'lines',jsonb_build_array(jsonb_build_object('item','시험공구','qty',10,'unit','EA','unit_price',1000)),'approvals',jsonb_build_array(jsonb_build_object('user_id',a,'required',false),jsonb_build_object('user_id',b,'required',true))));
 r:=public.dnm_v4_command('purchase_submit',payload,gen_random_uuid());prid:=(r->>'id')::uuid;
 SELECT * INTO rowx FROM public.dnm_v4_records WHERE id=prid;
 PERFORM public.test_assert((rowx.data->>'total')::numeric=11000,'server computes approved amount and VAT');
 PERFORM set_config('request.jwt.claim.sub',b::text,true);
 PERFORM public.test_error(format('SELECT public.dnm_v4_command(%L,%L::jsonb,gen_random_uuid())','purchase_decide',jsonb_build_object('id',prid,'version',rowx.version,'decision','APPROVE','reason','시험')::text),'현재 순번');
 PERFORM set_config('request.jwt.claim.sub',a::text,true);
 PERFORM public.dnm_v4_command('permissions',jsonb_build_object('profile_id',a,'capabilities',jsonb_build_array('approve'),'delegation_limit',100000,'delegation_until',(current_date+30)::text),gen_random_uuid());
 PERFORM public.test_error(format('SELECT public.dnm_v4_command(%L,%L::jsonb,gen_random_uuid())','purchase_decide',jsonb_build_object('id',prid,'version',rowx.version,'decision','FINAL','reason','전결 시험')::text),'필수결재자');
 PERFORM public.dnm_v4_command('purchase_decide',jsonb_build_object('id',prid,'version',rowx.version,'decision','APPROVE','reason','1차 승인'),gen_random_uuid());
 PERFORM set_config('request.jwt.claim.sub',b::text,true);SELECT * INTO rowx FROM public.dnm_v4_records WHERE id=prid;
 PERFORM public.dnm_v4_command('purchase_decide',jsonb_build_object('id',prid,'version',rowx.version,'decision','APPROVE','reason','최종 승인'),gen_random_uuid());
 PERFORM set_config('request.jwt.claim.sub',a::text,true);SELECT * INTO rowx FROM public.dnm_v4_records WHERE id=prid;
 PERFORM public.test_assert(rowx.state='APPROVED','last approver makes final approval');
 PERFORM public.dnm_v4_command('purchase_order',jsonb_build_object('id',prid,'version',rowx.version,'po_no','TEST-PO'),gen_random_uuid());
 SELECT * INTO rowx FROM public.dnm_v4_records WHERE id=prid;
 r:=public.dnm_v4_command('purchase_receive',jsonb_build_object('id',prid,'version',rowx.version,'line',0,'accepted',4,'rejected',0),gen_random_uuid());receiptid:=(r->>'id')::uuid;
 PERFORM public.test_assert((SELECT state='PARTIAL' FROM public.dnm_v4_records WHERE id=prid),'partial receipt state');
 SELECT * INTO rowx FROM public.dnm_v4_records WHERE id=prid;
 PERFORM public.test_error(format('SELECT public.dnm_v4_command(%L,%L::jsonb,gen_random_uuid())','purchase_receive',jsonb_build_object('id',prid,'version',rowx.version,'line',0,'accepted',7,'rejected',0)::text),'발주수량');
 PERFORM public.dnm_v4_command('purchase_receive',jsonb_build_object('id',prid,'version',rowx.version,'line',0,'accepted',6,'rejected',0),gen_random_uuid());
 SELECT * INTO rowx FROM public.dnm_v4_records WHERE id=receiptid;
 PERFORM public.dnm_v4_command('purchase_return',jsonb_build_object('id',receiptid,'version',rowx.version,'qty',1,'reason','반품 시험'),gen_random_uuid());
 PERFORM public.test_assert((SELECT state='PARTIAL' FROM public.dnm_v4_records WHERE id=prid),'return reopens remaining receipt');
 SELECT * INTO rowx FROM public.dnm_v4_records WHERE id=prid;
 PERFORM public.dnm_v4_command('purchase_receive',jsonb_build_object('id',prid,'version',rowx.version,'line',0,'accepted',1,'rejected',0),gen_random_uuid());
 SELECT * INTO rowx FROM public.dnm_v4_records WHERE id=prid;
 PERFORM public.test_error(format('SELECT public.dnm_v4_command(%L,%L::jsonb,gen_random_uuid())','settle',jsonb_build_object('id',prid,'version',rowx.version,'invoice_no','TEST-INV','invoice_amount',10000)::text),'증빙금액');
 r:=public.dnm_v4_command('settle',jsonb_build_object('id',prid,'version',rowx.version,'invoice_no','TEST-INV','invoice_amount',11000),gen_random_uuid());sid:=(r->>'id')::uuid;
 SELECT * INTO rowx FROM public.dnm_v4_records WHERE id=sid;
 PERFORM public.dnm_v4_command('paid',jsonb_build_object('id',sid,'version',rowx.version,'reference','TEST-NO-BANK-TRANSFER'),gen_random_uuid());
 PERFORM public.test_assert((SELECT state='PAID' FROM public.dnm_v4_records WHERE id=prid),'settlement paid reference only');
 PERFORM set_config('request.jwt.claim.sub',v::text,true);
 PERFORM public.test_error(format('SELECT public.dnm_v4_command(%L,%L::jsonb,gen_random_uuid())','save_order',payload::text),'권한');
 PERFORM public.test_error('SELECT public.dnm_v4_backup()','관리자');
 PERFORM set_config('request.jwt.claim.sub',a::text,true);
 PERFORM public.test_assert(public.dnm_v4_backup()->>'format'='dnm-cloud-business-v4','admin business backup');
END $$;
-- Row-level checks use the actual restricted database role, not postgres bypass.
SELECT set_config('request.jwt.claim.sub','44444444-4444-4444-8444-444444444444',false);
SET ROLE authenticated;
SELECT public.test_assert((SELECT count(*)=0 FROM public.dnm_v4_records WHERE kind='purchase'),'viewer cannot read others purchase records');
SELECT public.test_assert((SELECT count(*)>0 FROM public.dnm_v4_records WHERE kind='order'),'viewer can read operational order progress');
RESET ROLE;
SELECT count(*) AS business_rows, (SELECT count(*) FROM public.dnm_v4_requests) AS idempotent_requests FROM public.dnm_v4_records;
